-- =====================================================================
-- 0077 — MSA Studies and SPC Charts (two new KMR Apps, built to be used on their own)
--  • MSA Studies: Gage R&R (average & range and ANOVA), bias, linearity, stability and attribute agreement, entered by hand,
--    with a study register, decisions against AIAG MSA 4th ed., finalise / lock and print.
--  • SPC Charts: X̄-R, X̄-S, I-MR, p, np, c and u charts from readings typed or pasted in, run-rule signals with cause and action notes,
--    process capability (Cp, Cpk, Pp, Ppk) and print.
-- Process Documents and Calibration Hub keep their own SPC / MSA screens exactly as they are; nothing there is changed.
-- Needs 0076. Safe to re-run. Generated by scripts/make-msa-spc.py.
-- =====================================================================
do $$ begin
  if to_regprocedure('console.tsk_sample(uuid, text)') is null then raise exception 'Run 0076_actiontrack.sql first.'; end if;
end $$;

insert into console.products (code, name, description, app_path, seat_label, current_version, sort_order) values
  ('msa', 'MSA Studies', 'Measurement system analysis: Gage R&R (range and ANOVA), bias, linearity, stability and attribute agreement, entered by hand, with decisions and a study register', '/it/msa.html', 'users', '1.0.0', 13),
  ('spc', 'SPC Charts', 'Statistical process control: X-bar R, X-bar S, I-MR, p, np, c and u charts from typed or pasted readings, run-rule signals with cause and action, process capability Cp / Cpk / Pp / Ppk', '/it/spc.html', 'users', '1.0.0', 14)
on conflict (code) do nothing;
insert into console.releases (product_code, version, notes) values
  ('msa', '1.0.0', 'MSA Studies: Gage R&R range and ANOVA, bias, linearity, stability, attribute agreement, register, finalise and print'),
  ('spc', '1.0.0', 'SPC Charts: variable and attribute control charts, run rules, cause and action notes, capability, print') on conflict do nothing;
insert into console.prices (product_code, period, currency, unit_amount, min_seats, active, note)
select v.code, v.period, 'INR', v.amt, 3, true, 'Starting price list (0077) — per user, change in Console › Billing'
  from (values ('msa', 'month', 40), ('msa', 'year', 400), ('spc', 'month', 40), ('spc', 'year', 400)) v(code, period, amt)
 where not exists (select 1 from console.prices x where x.product_code = v.code and x.currency = 'INR' and x.period = v.period)
on conflict (product_code, period, currency) do nothing;
insert into public.app_listings (code, name, tagline, features, sort_order, is_active) values
  ('msa', 'MSA Studies', 'Prove your gauges before you trust the numbers: Gage R&R, bias, linearity, stability and attribute agreement.',
   E'Gage R&R by average-and-range and ANOVA\nBias, linearity and stability studies\nAttribute agreement with kappa, miss and false-alarm rates', 12, true),
  ('spc', 'SPC Charts', 'Control charts and capability from the readings you type in, with the signals explained.',
   E'X-bar R, X-bar S, I-MR, p, np, c and u charts\nRun rules with cause and action notes\nCp, Cpk, Pp and Ppk with histogram', 13, true)
on conflict (code) do update set name = excluded.name, tagline = excluded.tagline, features = excluded.features, is_active = true;

insert into console.app_features (product_code, name, detail, is_core, price_month, price_year, setup_fee, sort_order) values
  ('msa', 'Gage R&R', 'Gage R&R studies (range and ANOVA), study register, finalise and print', true, 15, 0, 5000, 10),
  ('msa', 'Bias, linearity & stability', 'Bias, linearity and stability studies', false, 10, 0, 3000, 20),
