delete from console.app_features f where f.product_code in ('msa', 'spc') and f.name = 'Core platform' and not exists (select 1 from console.invoice_lines il where il.feature_id = f.id);
update console.app_features set price_year = price_month * 10 where product_code in ('msa', 'spc') and price_year = 0;
select console.sync_app_price('msa'); select console.sync_app_price('spc');

-- ---------- tables ----------
create table if not exists console.msa_counters (
  customer_id uuid not null references console.customers(id) on delete cascade, key text not null, n bigint not null default 0, sample boolean not null default false, primary key (customer_id, key));
create table if not exists console.msa_studies (
  id uuid primary key default gen_random_uuid(), customer_id uuid not null references console.customers(id) on delete cascade,
  no text not null, type text not null check (type in ('grr', 'bias', 'linearity', 'stability', 'attribute')), title text,
  gauge_id text, gauge_name text, characteristic text, part_no text, part_name text, unit text, lsl numeric, usl numeric, study_date date, conducted_by text,
  config jsonb not null default '{}', data jsonb not null default '{}', results jsonb, decision text, notes text,
  status text not null default 'draft' check (status in ('draft', 'final')), finalised_by text, finalised_at timestamptz,
  sample boolean not null default false, created_by text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (customer_id, no));
create index if not exists msa_studies_cust on console.msa_studies (customer_id, study_date desc);
create table if not exists console.spc_counters (
  customer_id uuid not null references console.customers(id) on delete cascade, key text not null, n bigint not null default 0, sample boolean not null default false, primary key (customer_id, key));
create table if not exists console.spc_charts (
  id uuid primary key default gen_random_uuid(), customer_id uuid not null references console.customers(id) on delete cascade,
  no text not null, title text not null, part_no text, part_name text, characteristic text, process text, unit text,
  chart_type text not null check (chart_type in ('xr', 'xs', 'imr', 'p', 'np', 'c', 'u')), subgroup_size int not null default 5 check (subgroup_size between 1 and 25),
  lsl numeric, usl numeric, target numeric, rules jsonb not null default '{"rules":[1,2,3],"run":7,"trend":7}', frozen jsonb, limits_from int,
  status text not null default 'active' check (status in ('active', 'closed')), notes text, summary jsonb,
  sample boolean not null default false, created_by text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (customer_id, no));
create table if not exists console.spc_points (
  id uuid primary key default gen_random_uuid(), customer_id uuid not null references console.customers(id) on delete cascade,
  chart_id uuid not null references console.spc_charts(id) on delete cascade, seq int not null, label text, taken_at timestamptz,
  vals jsonb not null default '[]', note text, cause text, action text, sample boolean not null default false, created_by text, created_at timestamptz not null default now());
create index if not exists spc_points_chart on console.spc_points (chart_id, seq);
do $$ declare t text; begin foreach t in array array['msa_counters','msa_studies','spc_counters','spc_charts','spc_points'] loop
  execute format('alter table console.%I enable row level security', t);
  execute format('drop policy if exists %I on console.%I', t || '_staff', t);
  execute format('create policy %I on console.%I for all to authenticated using (console.is_staff()) with check (console.is_staff())', t || '_staff', t);
end loop; end $$;

